<?php
$page_title = 'Record Purchase';
require_once __DIR__ . '/../../includes/header.php';
/** @var mysqli $conn */
$conn = getDatabaseConnection();

$permissions = require __DIR__ . '/permissions.php';
$businessId = (int)($_SESSION['active_business_id'] ?? 0);
$membershipId = (int)($_SESSION['membership_id'] ?? 0);
requirePermission($conn, $membershipId, $businessId, $permissions['create']);

$config = getBusinessInventoryConfig($conn, $businessId);
$localNow = new DateTimeImmutable('now', new DateTimeZone($config['timezone']));
$role = getPreviewRole();
$roleQuery = $role ? '?role=' . rawurlencode($role) : '';
$csrfToken = generateCsrfToken();

$businessStmt = mysqli_prepare($conn, 'SELECT currency_code,business_name FROM businesses WHERE id=? LIMIT 1');
mysqli_stmt_bind_param($businessStmt, 'i', $businessId);mysqli_stmt_execute($businessStmt);
$business = mysqli_fetch_assoc(mysqli_stmt_get_result($businessStmt)) ?: [];
$currency = $business['currency_code'] ?? 'RWF';
$batchPrefix = getCompanyBatchPrefix((string)($business['business_name'] ?? 'COMPANY'));

$suppliers=[];$supplierStmt=mysqli_prepare($conn,'SELECT id,name,supplier_code FROM suppliers WHERE business_id=? AND is_active=1 ORDER BY name');mysqli_stmt_bind_param($supplierStmt,'i',$businessId);mysqli_stmt_execute($supplierStmt);$result=mysqli_stmt_get_result($supplierStmt);while($row=mysqli_fetch_assoc($result))$suppliers[]=$row;
$locations=[];$locationStmt=mysqli_prepare($conn,'SELECT id,name,code FROM business_locations WHERE business_id=? AND is_active=1 ORDER BY name');mysqli_stmt_bind_param($locationStmt,'i',$businessId);mysqli_stmt_execute($locationStmt);$result=mysqli_stmt_get_result($locationStmt);while($row=mysqli_fetch_assoc($result))$locations[]=$row;
$products=[];$productStmt=mysqli_prepare($conn,'SELECT id,name,sku,uom,track_batches,track_expiry FROM products WHERE business_id=? AND is_active=1 ORDER BY name');mysqli_stmt_bind_param($productStmt,'i',$businessId);mysqli_stmt_execute($productStmt);$result=mysqli_stmt_get_result($productStmt);while($row=mysqli_fetch_assoc($result))$products[]=$row;
?>

<main class="purchase-create-page">
  <nav class="purchase-form-breadcrumb"><a href="index<?php echo e($roleQuery); ?>">Purchases</a><span>/</span><span>Record Purchase</span></nav>
  <header class="purchase-form-header"><div><span>New supplier order</span><h1>Record Purchase</h1><p>Enter the order, products, and payment arrangement in one organized form.</p></div></header>

  <?php if(!$suppliers||!$locations||!$products):?><div class="purchase-form-warning">Before recording a purchase, register at least one active supplier, location, and product.</div><?php endif;?>

  <form action="backend<?php echo e($roleQuery); ?>" method="POST" id="recordPurchaseForm">
    <input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="idempotency_key" value="<?php echo e(createIdempotencyToken()); ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="return_to" value="purchase_create">
    <div class="purchase-form-layout">
      <div class="purchase-form-main">
        <section class="purchase-form-card"><div class="purchase-form-section-head"><div><h2>Order Information</h2><p>Supplier, delivery location, and purchase reference.</p></div><span>Required</span></div><div class="purchase-form-grid"><label>Purchase Order Number<input name="purchase_number" value="PO-<?php echo e($localNow->format('YmdHis')); ?>" required></label><label>Purchase Date<input type="datetime-local" name="purchase_date" value="<?php echo e($localNow->format('Y-m-d\TH:i')); ?>" required></label><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $supplier):?><option value="<?php echo (int)$supplier['id']; ?>"><?php echo e($supplier['name'].' · '.$supplier['supplier_code']); ?></option><?php endforeach;?></select></label><label>Delivery Location<select name="location_id" required><option value="">Select location</option><?php foreach($locations as $location):?><option value="<?php echo (int)$location['id']; ?>"><?php echo e($location['name'].' · '.$location['code']); ?></option><?php endforeach;?></select></label><label class="purchase-wide-field">Purchase Notes<textarea name="notes" rows="3" maxlength="2000" placeholder="Optional instructions or notes about this purchase"></textarea></label></div></section>

        <section class="purchase-form-card"><div class="purchase-form-section-head"><div><h2>Purchased Products</h2><p>Add every product, quantity, cost, selling price, and expiry when applicable.</p></div><button type="button" class="purchase-form-button purchase-form-button-secondary" onclick="addPurchaseItem()">Add Product</button></div><div class="purchase-item-labels"><span>Product</span><span>Quantity</span><span>Unit Cost</span><span>Sale Price</span><span>Expiry</span><span></span></div><div id="purchaseItemRows" class="purchase-item-rows"></div><div class="purchase-form-total"><span>Purchase Total</span><strong id="purchaseTotal">0.00 <?php echo e($currency); ?></strong></div></section>
      </div>

      <aside class="purchase-form-sidebar">
        <section class="purchase-form-card payment-card"><div class="purchase-form-section-head"><div><h2>Payment</h2><p>Choose whether this purchase was paid or is supplier debt.</p></div></div><div class="settlement-options"><label><input type="radio" name="settlement_type" value="DEBT" checked onchange="syncPurchasePayment()"><span><strong>Record as Debt</strong><small>No payment was made. The full value remains payable.</small></span></label><label><input type="radio" name="settlement_type" value="PAID" onchange="syncPurchasePayment()"><span><strong>Paid in Full</strong><small>A full payment record will be saved with this purchase.</small></span></label></div><div id="paidPurchaseFields" class="paid-purchase-fields" hidden><label>Payment Method<select name="payment_method" id="purchasePaymentMethod" onchange="syncPurchasePayment()"><option value="CASH">Cash</option><option value="MOBILE_MONEY">Phone / Mobile Money</option><option value="BANK_TRANSFER">Bank Transfer</option></select></label><label id="phonePaymentField" hidden>Telephone Number<input type="tel" name="payment_phone" id="paymentPhone" maxlength="32" placeholder="Telephone number used for payment"></label><div id="bankPaymentFields" class="bank-payment-fields" hidden><label>Bank Name<input name="bank_name" id="paymentBankName" maxlength="150" placeholder="Name of the bank"></label><label>Bank Account Number<input name="bank_account_number" id="paymentBankAccount" maxlength="120" placeholder="Account number used"></label></div><label id="paymentReferenceField">Payment Reference <span>Optional</span><input name="payment_reference" maxlength="120" placeholder="Receipt or transaction reference"></label><label>Payment Notes <span>Optional</span><textarea name="payment_notes" rows="2" maxlength="500" placeholder="Additional payment details"></textarea></label><div class="payment-method-note" id="paymentMethodNote">Cash payments require no additional details.</div></div><div class="debt-note" id="debtNote"><strong>Supplier debt</strong><p>This purchase will show as unpaid, with the full amount available for future payment tracking.</p></div></section>

        <section class="purchase-form-card purchase-form-help"><h2>Before Saving</h2><ul><li>Confirm the supplier and receiving location.</li><li>Check quantities and unit costs.</li><li>Select Paid or Debt accurately.</li><li>Phone and bank details are required only for those payment methods.</li></ul></section>
      </aside>
    </div>
    <footer class="purchase-form-actions"><div class="purchase-form-action-copy"><strong>Ready to record this purchase?</strong><span>Review the order, products, and payment details before saving.</span></div><div class="purchase-form-action-buttons"><a class="purchase-form-button purchase-form-button-secondary" href="index<?php echo e($roleQuery); ?>">Cancel and Return</a><button class="purchase-form-button purchase-form-button-primary" id="recordPurchaseButton" <?php echo !$suppliers||!$locations||!$products?'disabled':''; ?>><span class="purchase-button-icon" aria-hidden="true"><svg viewBox="0 0 20 20" focusable="false"><path d="M4 3h10l2 2v12H4V3Zm3 0v5h6V3M7 13h6"/></svg></span><span class="purchase-button-label">Record Purchase</span></button></div></footer>
  </form>
</main>

