ase-fields textarea{width:100%;min-height:39px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--text);font:inherit;font-size:10px}.purchase-form-grid textarea,.paid-purchase-fields textarea{resize:vertical}.purchase-wide-field{grid-column:1/-1}.purchase-item-labels,.purchase-item-row{display:grid;grid-template-columns:minmax(190px,1.5fr) 90px 115px 115px 135px 34px;gap:8px;align-items:start}.purchase-item-labels{padding:11px 15px 6px;color:var(--text3);font-size:8px;text-transform:uppercase}.purchase-item-rows{padding:0 15px}.purchase-item-row{padding:9px 0;border-top:1px solid var(--table-border)}.purchase-item-row select,.purchase-item-row input{width:100%;min-height:37px;padding:7px 9px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--text);font:inherit;font-size:9.5px}.purchase-item-row small{display:block;margin-top:4px;color:var(--text3);font-size:8px}.purchase-remove-item{min-height:35px;padding:5px;border:1px solid var(--border);border-radius:7px;background:var(--card);color:var(--red);cursor:pointer}.purchase-form-total{display:flex;align-items:center;justify-content:flex-end;gap:18px;padding:13px 15px;border-top:1px solid var(--border);background:var(--bg);font-size:10px}.purchase-form-total strong{color:var(--blue);font-size:14px}.settlement-options{display:grid;gap:7px;padding:13px}.settlement-options label{display:flex;align-items:flex-start;gap:9px;padding:11px;border:1px solid var(--border);border-radius:9px;background:var(--bg);cursor:pointer}.settlement-options input{margin-top:2px;accent-color:var(--blue)}.settlement-options strong,.settlement-options small{display:block}.settlement-options strong{font-size:9.5px}.settlement-options small{margin-top:3px;color:var(--text3);font-size:8px;line-height:1.4}.paid-purchase-fields{display:grid;gap:11px;padding:13px;border-top:1px solid var(--border)}.paid-purchase-fields label>span{color:var(--text3);font-size:8px;font-weight:400}.bank-payment-fields{display:grid;gap:11px}.payment-method-note,.debt-note{margin:0 13px 13px;padding:10px;border-radius:8px;background:var(--blue-bg);color:var(--text2);font-size:8.5px}.debt-note strong{font-size:9px}.debt-note p{margin:4px 0 0;line-height:1.45}.purchase-form-help{padding:14px}.purchase-form-help ul{display:grid;gap:7px;margin:10px 0 0;padding-left:17px;color:var(--text2);font-size:8.5px;line-height:1.45}.purchase-form-actions{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:16px 0 4px;padding:16px 18px;border:1px solid var(--border);border-radius:12px;background:var(--card);position:relative}.purchase-form-action-copy{display:flex;flex-direction:column;gap:4px;min-width:0}.purchase-form-action-copy strong{color:var(--text);font-size:10.5px}.purchase-form-action-copy span{color:var(--text3);font-size:8.5px}.purchase-form-action-buttons{display:flex;align-items:center;justify-content:flex-end;gap:9px;flex-shrink:0}.purchase-form-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:40px;padding:9px 15px;border:1px solid transparent;border-radius:9px;font:inherit;font-size:9.5px;font-weight:700;text-decoration:none;cursor:pointer;transition:transform .16s ease,box-shadow .16s ease,background .16s ease,border-color .16s ease}.purchase-form-button-primary{min-width:158px;background:linear-gradient(135deg,var(--blue),#315ee8);border-color:var(--blue);color:#fff;box-shadow:0 5px 14px rgba(37,99,235,.2)}.purchase-form-button-primary:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 8px 18px rgba(37,99,235,.27)}.purchase-form-button-secondary{background:var(--card);border-color:var(--border);color:var(--text2)}.purchase-form-button-secondary:hover{background:var(--bg);border-color:var(--text3)}.purchase-form-button:focus-visible{outline:3px solid var(--blue-bg);outline-offset:2px}.purchase-button-icon{display:inline-flex;width:16px;height:16px}.purchase-button-icon svg{width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.purchase-form-button:disabled{opacity:.5;cursor:not-allowed;box-shadow:none}
